export class OrderService {
  async processOrder(
    orderId: string,
    customerId: string,
    items: any[],
    paymentMethod: string,
    shippingAddress: string,
    promoCode: string,
    isGuestCheckout: boolean
  ) {
    // Validate items
    for (const item of items) {
      if (!item.id || !item.quantity || item.quantity < 1) throw new Error('Invalid item');
      const inStock = await this.inventory.checkStock(item.id, item.quantity);
      if (!inStock) throw new Error(`Item ${item.id} out of stock`);
    }
    // Calculate total
    let total = 0;
    for (const item of items) {
      const price = await db.query('SELECT price FROM products WHERE id=$1', [item.id]);
      total += price.rows[0].price * item.quantity;
    }
    if (promoCode) {
      const promo = await db.query('SELECT discount FROM promos WHERE code=$1', [promoCode]);
      if (promo.rows.length) total *= (1 - promo.rows[0].discount);
    }
    // Charge
    const payment = await this.payments.charge(customerId, total, paymentMethod);
    if (!payment.success) throw new Error('Payment failed');
    // Persist
    const order = await db.query(
      'INSERT INTO orders (customer_id, total, shipping_address, promo_code) VALUES ($1,$2,$3,$4) RETURNING id',
      [customerId, total, shippingAddress, promoCode]
    );
    // Decrement stock
    for (const item of items) {
      await this.inventory.decrementStock(item.id, item.quantity);
    }
    // Notify
    if (isGuestCheckout) {
      await this.email.sendGuestOrderConfirmation(shippingAddress, order.rows[0].id);
    } else {
      const customer = await db.query('SELECT email FROM customers WHERE id=$1', [customerId]);
      await this.email.sendOrderConfirmation(customer.rows[0].email, order.rows[0].id);
    }
    return order.rows[0].id;
  }
}
