class UserManager:
    def __init__(self, db, redis, smtp, s3):
        self.db = db
        self.redis = redis
        self.smtp = smtp
        self.s3 = s3
        self.password_min_length = 8
        self.session_ttl = 3600
        self.avatar_max_size = 5 * 1024 * 1024
        self.allowed_avatar_types = ['image/jpeg', 'image/png']

    def register(self, email, password, first_name, last_name, birth_date, country, referral_code=None):
        if not email or '@' not in email:
            raise ValueError('Invalid email')
        if len(password) < self.password_min_length:
            raise ValueError('Password too short')
        existing = self.db.query('SELECT id FROM users WHERE email=%s', [email])
        if existing:
            raise ValueError('Email already registered')
        hashed = bcrypt.hashpw(password.encode(), bcrypt.gensalt())
        user_id = self.db.insert('users', {
            'email': email, 'password': hashed,
            'first_name': first_name, 'last_name': last_name,
            'birth_date': birth_date, 'country': country
        })
        if referral_code:
            ref = self.db.query('SELECT id FROM referrals WHERE code=%s', [referral_code])
            if ref:
                self.db.insert('referral_uses', {'referral_id': ref[0]['id'], 'new_user_id': user_id})
        self.smtp.send(email, 'Welcome!', f'Hi {first_name}, thanks for joining.')
        return user_id

    def login(self, email, password, ip_address, user_agent):
        user = self.db.query('SELECT * FROM users WHERE email=%s', [email])
        if not user or not bcrypt.checkpw(password.encode(), user[0]['password']):
            raise ValueError('Invalid credentials')
        token = secrets.token_hex(32)
        self.redis.setex(f'session:{token}', self.session_ttl, user[0]['id'])
        self.db.insert('login_events', {'user_id': user[0]['id'], 'ip': ip_address, 'ua': user_agent})
        return token

    def upload_avatar(self, user_id, file_data, content_type, filename):
        if len(file_data) > self.avatar_max_size:
            raise ValueError('File too large')
        if content_type not in self.allowed_avatar_types:
            raise ValueError('Invalid file type')
        key = f'avatars/{user_id}/{filename}'
        self.s3.put_object(Bucket='user-uploads', Key=key, Body=file_data, ContentType=content_type)
        self.db.update('users', {'avatar_key': key}, {'id': user_id})

    def change_password(self, user_id, old_password, new_password):
        user = self.db.query('SELECT password FROM users WHERE id=%s', [user_id])
        if not bcrypt.checkpw(old_password.encode(), user[0]['password']):
            raise ValueError('Incorrect password')
        if len(new_password) < self.password_min_length:
            raise ValueError('Password too short')
        hashed = bcrypt.hashpw(new_password.encode(), bcrypt.gensalt())
        self.db.update('users', {'password': hashed}, {'id': user_id})

    def deactivate(self, user_id, reason):
        self.db.update('users', {'active': False, 'deactivation_reason': reason}, {'id': user_id})
        self.redis.delete(f'session:{user_id}')
        user = self.db.query('SELECT email, first_name FROM users WHERE id=%s', [user_id])
        self.smtp.send(user[0]['email'], 'Account deactivated', f'Hi {user[0]["first_name"]}, your account has been deactivated.')
